import boto3

# Runtime do BDA: processa o asset de forma assíncrona e grava o JSON no S3.
bda = boto3.client("bedrock-data-automation-runtime", region_name="us-east-1")

resp = bda.invoke_data_automation_async(
    inputConfiguration={
        "s3Uri": "s3://meu-bucket/entrada/nota-fiscal.pdf"
    },
    outputConfiguration={
        "s3Uri": "s3://meu-bucket/saida/"
    },
    # O projeto define Standard output ou um Blueprint (Custom output).
    dataAutomationConfiguration={
        "dataAutomationProjectArn": "arn:aws:bedrock:us-east-1:123456789012:data-automation-project/minha-nfe"
    },
)

# Acompanhe o job; o resultado sai como JSON no s3Uri de saida.
print(resp["invocationArn"])
